import{_ as t,o as a,c as s,a3 as r}from"./chunks/framework.DAK02U1-.js";const g=JSON.parse('{"title":"Cross-Compiling","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Cross-Compiling | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/xclang/guide/cross-compiling"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/xclang/guide/cross-compiling"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/guide/cross-compiling"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/guide/cross-compiling"}]]},"headers":[],"relativePath":"xclang/guide/cross-compiling.md","filePath":"en/xclang/guide/cross-compiling.md","lastUpdated":1791238464000}'),i={name:"xclang/guide/cross-compiling.md"};function o(n,e,d,l,h,c){return a(),s("div",null,[...e[0]||(e[0]=[r(`<h1 id="cross-compiling" tabindex="-1">Cross-Compiling <a class="header-anchor" href="#cross-compiling" aria-label="Permalink to &quot;Cross-Compiling&quot;">​</a></h1><p>Add <code>--target</code>. The sysroot, the runtimes and the linker of every target come with xclang, so nothing else is needed.</p><h2 id="build-for-another-target" tabindex="-1">Build for Another Target <a class="header-anchor" href="#build-for-another-target" aria-label="Permalink to &quot;Build for Another Target&quot;">​</a></h2><p>From the <a href="./quick-start">quick start</a> directory, with <code>hello.cpp</code> from there, build for Windows on Arm:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pixi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clang++</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -O2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target=aarch64-w64-mingw32</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello.cpp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello-windows-arm64.exe</span></span></code></pre></div><p>The same command builds for any of the six targets:</p><table tabindex="0"><thead><tr><th>target</th><th>runs on</th><th>builds on</th></tr></thead><tbody><tr><td><code>x86_64-unknown-linux-gnu</code></td><td>Linux x64, glibc 2.17 or later</td><td>every host</td></tr><tr><td><code>aarch64-unknown-linux-gnu</code></td><td>Linux arm64, glibc 2.17 or later</td><td>every host</td></tr><tr><td><code>x86_64-w64-mingw32</code></td><td>Windows x64, 10 or later</td><td>every host</td></tr><tr><td><code>aarch64-w64-mingw32</code></td><td>Windows arm64, 10 or later</td><td>every host</td></tr><tr><td><code>aarch64-apple-darwin</code></td><td>macOS arm64, 13 or later</td><td>macOS hosts</td></tr><tr><td><code>x86_64-apple-darwin</code></td><td>macOS x64, 13 or later</td><td>macOS hosts</td></tr></tbody></table><p>The macOS targets build against Xcode&#39;s SDK, which xclang cannot redistribute, so they build on macOS hosts only. clang&#39;s other spellings of the targets, such as <code>x86_64-pc-linux-gnu</code> or <code>arm64-apple-macos</code>, work too (<a href="./../reference/targets#targets">targets</a>).</p><h2 id="in-your-build-system" tabindex="-1">In Your Build System <a class="header-anchor" href="#in-your-build-system" aria-label="Permalink to &quot;In Your Build System&quot;">​</a></h2><ul><li>CMake: the toolchain file with <code>-DXCLANG_TARGET=&lt;target&gt;</code> (<a href="./../integrations/cmake#build-for-another-target">CMake</a>).</li><li>Bazel: <code>--platforms=@xclang//platforms:&lt;target&gt;</code> (<a href="./../integrations/bazel#build-for-another-target">Bazel</a>).</li><li>Meson, Make and others: the compiler with <code>--target</code> (<a href="./../integrations/clang">Make and Meson</a>).</li><li>cargo: xclang as the C compiler and linker of a Rust target (<a href="./../integrations/cargo">Rust and Cargo</a>).</li></ul><h2 id="run-the-result" tabindex="-1">Run the Result <a class="header-anchor" href="#run-the-result" aria-label="Permalink to &quot;Run the Result&quot;">​</a></h2><p>Check what was built:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pixi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> llvm-readobj</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --file-headers</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello-windows-arm64.exe</span></span></code></pre></div><p>It prints, among the headers, <code>Format: COFF-ARM64</code> and <code>Arch: aarch64</code>.</p><p>Copy the program to a machine of its target and run it there; nothing has to be installed. A Linux program runs on any distribution with glibc 2.17 or later, and a Windows program on Windows 10 or later. Some hosts also run other targets:</p><ul><li>arm64 macOS runs x86_64 macOS programs, through Rosetta.</li><li>Windows on Arm runs x86_64 Windows programs, through emulation.</li></ul><p><code>hello-windows-arm64.exe</code> prints <code>hello from xclang</code>. Running tests for another target on its own runner is in <a href="./../integrations/ci#build-on-one-runner-run-on-another">CI</a>.</p><h2 id="how-clang-finds-the-target-s-files" tabindex="-1">How Clang Finds the Target&#39;s Files <a class="header-anchor" href="#how-clang-finds-the-target-s-files" aria-label="Permalink to &quot;How Clang Finds the Target&#39;s Files&quot;">​</a></h2><p>Cross-compiling C++ needs, for the target, a compiler that emits its code, its C library (the sysroot), a C++ standard library and the low-level runtimes, and a linker for its object format. clang emits code for every architecture LLVM supports, and lld links ELF, COFF and Mach-O. So the compiler and linker are one program for every target, and xclang adds the rest.</p><p>For each <code>--target</code>, clang reads a config file from its own <code>bin/</code> directory. The file is named after clang&#39;s normalized spelling of the triple: <code>aarch64-w64-windows-gnu.cfg</code> for <code>--target=aarch64-w64-mingw32</code>. It names the sysroot of the target, <code>xclang/aarch64-w64-mingw32/</code>, and its runtimes:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>--sysroot=&lt;CFGDIR&gt;/../aarch64-w64-mingw32</span></span>
<span class="line"><span>-rtlib=compiler-rt</span></span>
<span class="line"><span>-unwindlib=libunwind</span></span>
<span class="line"><span>-stdlib=libc++</span></span>
<span class="line"><span>-fuse-ld=lld</span></span></code></pre></div><p>The rest follows from the MinGW driver of clang. There is no wrapper script, no environment variable and no state outside the toolchain directory. The same command means the same thing on every machine.</p><p>The config files apply to native builds too. <code>clang++ hello.cpp</code> on Linux compiles against glibc 2.17, not the glibc of the machine. So a program built on a new distribution runs on an old one. <code>--no-default-config</code> skips the config file, and gives a bare compiler that uses the system&#39;s own headers and libraries (<a href="./../design/toolchain#a-config-file-per-target">config files</a>).</p><p>Every target follows one rule: a program needs nothing but the system libraries of its OS (<a href="./../design/hermeticity">hermeticity</a>). Each target also has a tier, which says how it is tested (<a href="./../reference/targets#tiers">tiers</a>).</p><h2 id="not-yet-supported" tabindex="-1">Not Yet Supported <a class="header-anchor" href="#not-yet-supported" aria-label="Permalink to &quot;Not Yet Supported&quot;">​</a></h2><p>The toolchain has the six targets above, and no others. xclang&#39;s vision is what rustup and cross-rs do for Rust. Every other target is an archive of its own, fetched when a build needs it. Vendor SDKs are fetched from the vendor by the user. None of it is in a release:</p><table tabindex="0"><thead><tr><th></th><th>status</th></tr></thead><tbody><tr><td><a href="./../design/roadmap#xclang-command">The <code>xclang</code> command</a>, which fetches vendor SDKs</td><td><span class="status-badge warn">Unreleased</span></td></tr><tr><td><a href="./../design/roadmap#target-archives">Target archives for <code>xclang target add</code></a></td><td><span class="status-badge note">Planned</span></td></tr><tr><td><a href="./../design/roadmap#msvc">MSVC-ABI targets</a></td><td><span class="status-badge warn">Unreleased</span></td></tr><tr><td><a href="./../design/roadmap#musl">musl targets</a></td><td><span class="status-badge note">Planned</span></td></tr><tr><td><a href="./../design/roadmap#macos-any-host">macOS targets from Linux or Windows</a></td><td><span class="status-badge note">In research</span></td></tr><tr><td><a href="./../design/roadmap#wasm">WebAssembly</a>, <a href="./../design/roadmap#linux-architectures">more Linux architectures</a>, <a href="./../design/roadmap#android">Android</a></td><td><span class="status-badge note">Considered</span></td></tr></tbody></table><p>The <a href="./../design/roadmap#targets">roadmap</a> lists every target, with its tier and status.</p>`,28)])])}const m=t(i,[["render",o]]);export{g as __pageData,m as default};
